/**
 * Stackra file contract:
 * Purpose: what an `AiMark` says: the action can be run by the viewer's agent, the record was changed by an agent, or
 *          the content was generated by AI.
 * Boundary: the values only; the mark is derived (from the manifest's tool entry and the viewer's permissions, or the
 *           record's provenance), never set by hand in a screen.
 * Runtime: isomorphic
 * Governing contract: ADR 0360 (decision 11: the AI marker, the provenance mark and the consumer label).
 */

/** The kinds of AI mark. */
// shortcut: a frozen tuple until @stackra/contracts ships Enum.of here (ADR 0128); the kinds carry no labels.
export const AiMarkKind = Object.freeze(["capable", "changed", "generated"] as const);

/** One kind of AI mark. */
export type AiMarkKind = (typeof AiMarkKind)[number];
